    private final List<String> booked = new ArrayList<>();
    private CarrierGateway carrier = orderId -> {
        booked.add(orderId);
        return "TRK-" + orderId;
    };
    private final OrderService service = new OrderService(new OrderRepository(), (CarrierGateway) orderId -> carrier.book(orderId));

    private String placeOrder() {
        return service.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));
    }

